<script setup lang="ts">
import {computed,ref} from 'vue'
import {promptParagraphs} from '../../electron/prompt-layout'
import type {ImageGridBlock} from '../../electron/types'
import {importMedia} from '../media-store'
import AssetImage from './AssetImage.vue'
const props=defineProps<{modelValue:ImageGridBlock[];editable?:boolean;prompt?:string}>()
const emit=defineEmits<{'update:modelValue':[value:ImageGridBlock[]];busy:[value:boolean]}>()
const error=ref(''),busy=ref(false),drag=ref<string|null>(null)
const paragraphs=computed(()=>promptParagraphs(props.prompt||''))
function position(grid:ImageGridBlock,event:Event){const value=(event.target as HTMLSelectElement).value;patch(grid.id,{afterParagraph:value==='end'?undefined:Number(value)})}
const clone=()=>JSON.parse(JSON.stringify(props.modelValue)) as ImageGridBlock[]
function patch(id:string,value:Partial<ImageGridBlock>){emit('update:modelValue',props.modelValue.map(grid=>grid.id===id?{...grid,...value}:grid))}
function caption(grid:ImageGridBlock,id:string,value:string){patch(grid.id,{items:grid.items.map(item=>item.id===id?{...item,caption:value}:item)})}
function move(grid:ImageGridBlock,id:string,offset:number){const items=[...grid.items],index=items.findIndex(item=>item.id===id),next=index+offset;if(next<0||next>=items.length)return;items.splice(next,0,items.splice(index,1)[0]);patch(grid.id,{items})}
function drop(grid:ImageGridBlock,target:string){if(!drag.value)return;const index=grid.items.findIndex(item=>item.id===drag.value),next=grid.items.findIndex(item=>item.id===target);if(index>=0&&next>=0)move(grid,drag.value,next-index);drag.value=null}
async function upload(grid:ImageGridBlock,event:Event,replace?:string){
 const input=event.target as HTMLInputElement,files=Array.from(input.files||[]);if(!files.length)return
 busy.value=true;emit('busy',true);error.value=''
 try{if(grid.items.length+(replace?0:files.length)>40)throw new Error('每个网格最多 40 张图片');const imported:Awaited<ReturnType<typeof importMedia>>[]=[];for(const file of files)imported.push(await importMedia(file,'image'));const latest=clone().find(item=>item.id===grid.id);if(!latest)return;const items=replace?latest.items.map(item=>item.id===replace?{...item,assetId:imported[0].id}:item):[...latest.items,...imported.map(asset=>({id:crypto.randomUUID(),assetId:asset.id,caption:''}))];patch(grid.id,{items})}catch(e){error.value=(e as Error).message}finally{busy.value=false;emit('busy',false);input.value=''}
}
</script>
<template><div class="image-grids"><p v-if="error" role="alert" class="form-error">{{error}}</p><section v-for="grid in modelValue" :key="grid.id" class="image-grid-block">
 <div v-if="editable" class="grid-toolbar"><strong>图文网格</strong><label>位置<select :value="grid.afterParagraph===undefined?'end':String(grid.afterParagraph)" :aria-label="`图文网格 ${modelValue.indexOf(grid)+1} 插入位置`" @change="position(grid,$event)"><option value="end">题干末尾</option><option value="0">题干开头</option><option v-for="(paragraph,index) in paragraphs" :key="index" :value="String(index+1)">第 {{index+1}} 段后 · {{paragraph.trim().slice(0,14)||'空白段落'}}</option><option v-if="grid.afterParagraph!==undefined&&grid.afterParagraph>paragraphs.length" :value="String(grid.afterParagraph)">原第 {{grid.afterParagraph}} 段后（当前按末尾显示）</option></select></label><label>列数<select :value="grid.columns" @change="patch(grid.id,{columns:Number(($event.target as HTMLSelectElement).value) as 2|3|4})"><option :value="2">2 列</option><option :value="3">3 列</option><option :value="4">4 列</option></select></label><label>图片<select :value="grid.fit" @change="patch(grid.id,{fit:($event.target as HTMLSelectElement).value as 'contain'|'cover'})"><option value="contain">完整显示</option><option value="cover">裁剪铺满</option></select></label><label>高度<input type="number" min="60" max="400" :value="grid.imageHeight" @change="patch(grid.id,{imageHeight:Math.min(400,Math.max(60,Number(($event.target as HTMLInputElement).value)||160))})" /></label><label>间距<input type="number" min="0" max="48" :value="grid.gap" @change="patch(grid.id,{gap:Math.min(48,Math.max(0,Number(($event.target as HTMLInputElement).value)||0))})" /></label><label>对齐<select :value="grid.align" @change="patch(grid.id,{align:($event.target as HTMLSelectElement).value as 'start'|'center'|'end'})"><option value="start">左对齐</option><option value="center">居中</option><option value="end">右对齐</option></select></label><label class="grid-upload">＋ 图片<input type="file" accept="image/png,image/jpeg,image/webp" multiple :disabled="busy" @change="upload(grid,$event)" /></label><button type="button" class="text-button" :disabled="busy" @click="emit('update:modelValue',modelValue.filter(item=>item.id!==grid.id))">删除网格</button></div>
 <div class="grid-items" :style="{'--grid-columns':grid.columns,gap:grid.gap+'px',textAlign:grid.align==='start'?'left':grid.align==='end'?'right':'center'}"><figure v-for="(item,index) in grid.items" :key="item.id" :draggable="editable&&!busy" @dragstart="drag=item.id" @dragover.prevent @drop.prevent="drop(grid,item.id)"><AssetImage :asset-id="item.assetId" :alt="item.caption" :style="{height:grid.imageHeight+'px',objectFit:grid.fit}"/><figcaption v-if="!editable&&item.caption">{{item.caption}}</figcaption><template v-if="editable"><input :value="item.caption" maxlength="2000" placeholder="图片下方文字" :aria-label="`图片 ${index+1} 说明`" @input="caption(grid,item.id,($event.target as HTMLInputElement).value)" /><div class="grid-item-actions"><button type="button" :disabled="busy||index===0" aria-label="向前移动图片" @click="move(grid,item.id,-1)">←</button><button type="button" :disabled="busy||index===grid.items.length-1" aria-label="向后移动图片" @click="move(grid,item.id,1)">→</button><label>替换<input type="file" accept="image/png,image/jpeg,image/webp" :disabled="busy" @change="upload(grid,$event,item.id)" /></label><button type="button" :disabled="busy" @click="patch(grid.id,{items:grid.items.filter(value=>value.id!==item.id)})">删除</button></div></template></figure></div><p v-if="editable&&!grid.items.length" class="grid-empty">点击“＋ 图片”一次上传多张图片，拖动图片或使用箭头调整顺序。</p>
</section></div></template>
<style scoped>
.image-grids{display:grid;gap:18px;margin:16px 0;min-width:0}.grid-toolbar{display:flex;align-items:center;flex-wrap:wrap;gap:12px;padding:12px;border-bottom:1px solid var(--line);font-size:12px}.grid-toolbar select{max-width:220px}.grid-toolbar label{display:flex;align-items:center;gap:6px}.grid-toolbar input[type=number]{width:64px}.grid-toolbar select,.grid-toolbar input{padding:7px;border:1px solid var(--line);border-radius:6px;background:var(--surface);color:var(--ink)}.image-grid-block:has(.grid-toolbar){border:1px solid var(--line);border-radius:10px;overflow:hidden}.grid-items{display:grid;grid-template-columns:repeat(var(--grid-columns),minmax(0,1fr));padding:12px;min-width:0}.grid-items figure{margin:0;min-width:0}.grid-items img{width:100%;display:block;background:#fff;border-radius:4px}.grid-items figcaption{font-size:14px;line-height:1.65;margin-top:8px;white-space:pre-wrap;overflow-wrap:anywhere}.grid-items input{margin-top:8px;width:100%;min-width:0;padding:8px;border:1px solid var(--line);border-radius:6px;background:var(--surface);color:var(--ink)}.grid-item-actions{display:flex;flex-wrap:wrap;gap:10px;font-size:12px;margin-top:8px}.grid-upload,.grid-item-actions label{cursor:pointer;color:var(--blue)}input[type=file]{display:none}.grid-empty{font-size:12px;color:var(--muted);padding:0 12px 12px}button:disabled{opacity:.35}
</style>
